/// Deterministic payload fingerprint (no Pedersen).
/// Must match `credentialPayloadFingerprint` in affix-api/src/mldsa-crypto.ts.
pub fn credential_payload_fingerprint(
    issuer_pubkey_hash: Field,
    schema_id: Field,
    claim_hash: Field,
    valid_from: Field,
    valid_until: Field,
) -> Field {
    issuer_pubkey_hash + schema_id * 2 + claim_hash * 4 + valid_from * 8 + valid_until * 16
}

/// Binds witness fields to the ML-DSA-65 signed payload digest supplied by the verifier.
pub fn verify_mldsa_signed_payload(
    issuer_pubkey_hash: Field,
    schema_id: Field,
    claim_hash: Field,
    valid_from: Field,
    valid_until: Field,
    payload_digest: Field,
) -> bool {
    let fingerprint =
        credential_payload_fingerprint(issuer_pubkey_hash, schema_id, claim_hash, valid_from, valid_until);
    fingerprint == payload_digest
}

/// Legacy alias kept for template compatibility during migration.
pub fn verify_payload_digest(
    issuer_pubkey_hash: Field,
    schema_id: Field,
    claim_hash: Field,
    valid_from: Field,
    valid_until: Field,
    payload_digest: Field,
) -> bool {
    verify_mldsa_signed_payload(
        issuer_pubkey_hash,
        schema_id,
        claim_hash,
        valid_from,
        valid_until,
        payload_digest,
    )
}

pub fn verify_attestation_binding(
    issuer_pubkey_hash: Field,
    payload_digest: Field,
    attestation_digest: Field,
) -> bool {
    attestation_digest == payload_digest + issuer_pubkey_hash
}

