pub fn derive_nullifier(secret: Field, context_id: Field, credential_id: Field) -> Field {
    secret + context_id * 2 + credential_id * 4
}

pub fn verify_nullifier(
    secret: Field,
    context_id: Field,
    credential_id: Field,
    expected: Field,
) -> bool {
    derive_nullifier(secret, context_id, credential_id) == expected
}
